<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { Check, CircleAlert, Clock3, FileStack, Plus } from 'lucide-vue-next'; import { api, type Dashboard } from '../lib/api'; import TaskTable from '../components/TaskTable.vue'
defineEmits<{navigate:[page:string]}>(); const data=ref<Dashboard|null>(null); onMounted(async()=>data.value=await api.dashboard()); const cards=computed(()=>data.value?[['今日任务',data.value.today,FileStack],['已完成',data.value.completed,Check],['处理中',data.value.processing,Clock3],['失败',data.value.failed,CircleAlert]]:[]); const peak=computed(()=>Math.max(1,...(data.value?.daily.map(day=>day.count)??[1]))); const fmt=(bytes:number)=>bytes<1024*1024?`${Math.ceil(bytes/1024)} KB`:`${(bytes/1024/1024/1024).toFixed(2)} GB`
</script>
<template><section class="page dashboard"><header class="page-head"><div><h1>概览</h1><p>查看处理任务的整体状态与近期活动</p></div><button class="primary" @click="$emit('navigate','editor')"><Plus :size="18"/>新建处理</button></header><div class="stats"><article v-for="([label,value,icon], index) in cards" :key="index"><component :is="icon" :size="22"/><div><span>{{label}}</span><strong>{{value}}</strong></div></article></div><div class="dashboard-grid"><article class="panel chart-panel"><div class="panel-head"><h2>每日处理数量</h2><span>近 7 天 · {{fmt(data?.totalBytes ?? 0)}}</span></div><div class="bar-chart"><div v-for="day in data?.daily ?? []" :key="day.label"><i :style="{height:Math.max(4,day.count/peak*100)+'%'}"></i><small>{{day.label}}</small></div></div></article><article class="panel donut-panel"><h2>图片与视频</h2><div class="donut" :style="{background:`conic-gradient(var(--blue) 0 ${(data?.imageCount||0)/Math.max(1,(data?.imageCount||0)+(data?.videoCount||0))*100}%, #d7e4fb 0 100%)`}"><span>{{data?.successRate ?? 0}}%<small>成功率</small></span></div><p><i class="dot blue"></i> 图片 {{data?.imageCount ?? 0}}　<i class="dot pale"></i> 视频 {{data?.videoCount ?? 0}}</p></article></div><article class="panel recent"><div class="panel-head"><h2>近期任务</h2><span>累计 {{data?.totalTasks ?? 0}} 个任务</span></div><TaskTable :tasks="data?.recent ?? []"/></article></section></template>
